-- PT113-S2-Q10. Batch 06.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT113-S2-Q10$batch06$ AND q.stimulus=$batch06$Mark: To convey an understanding of past events, a historian should try to capture what it was like to experience those events. For instance, a foot soldier in the Battle of Waterloo knew through direct experience what the battle was like, and it is this kind of knowledge that the historian must capture.
Carla: But how do you go about choosing whose perspective is the valid one? Is the foot soldier's perspective more valid than that of a general? Should it be a French or an English soldier? Your approach would generate a biased version of history, and to avoid that, historians must stick to general and objective characterizations of the past.$batch06$ AND q.prompt=$batch06$Carla does which one of the following in disputing Mark's position?$batch06$ AND q.correct_choice=$batch06$C$batch06$) THEN RAISE EXCEPTION 'Question changed: PT113-S2-Q10'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch06$PT113-S2-Q10$batch06$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT113-S2-Q10'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT113-S2-Q10$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Conclusion$batch06$, $batch06$(Carla) Mark's approach would produce biased history.$batch06$), (1, $batch06$Evidence$batch06$, $batch06$Someone has to choose whose experience counts: the foot soldier or the general, the French or the English.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$Carla does not deny that a soldier knew what the battle was like. Her point is that Mark's method requires picking one perspective, and the pick itself slants the result. The act of choosing is the problem.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Showing that the selection Mark's approach requires would distort history.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT113-S2-Q10$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$Carla does not dispute any historical fact Mark mentions.$batch06$), ($batch06$B$batch06$, $batch06$Whether one person can understand another's feelings never comes up.$batch06$), ($batch06$C$batch06$, $batch06$The selection is choosing whose perspective to use. The distortion is the bias Carla says would result.$batch06$), ($batch06$D$batch06$, $batch06$Mark does not describe a kind of history he deplores.$batch06$), ($batch06$E$batch06$, $batch06$No one's professional motives are mentioned.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT113-S2-Q10$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
